\label{thm:ABBP}
For every symmetric convex body $L\subset{\mathbb R}^n$ and every
$1\leq k\leq n-1$, there exists a rank $k$ orthogonal projection $P$ such
that
\begin{equation}\label{eq:ABBP}
 {\rm vr}(PL,B_2^k)
 \leq C\sqrt{\frac{n}{n-k}}
 \ln\left(1+\frac{n}{n-k}\right),
\end{equation}
where $C>0$ is an absolute constant.

\label{thm:euclidean-large}
There exist absolute constants $c,C>0$ such that for every $n/2<k<n$,
\[
 c\sqrt{\frac{n}{n-k}}
 \leq {\rm povr}_k(B_2^n)
 \leq C\sqrt{\frac{n}{n-k}}
 \ln\left(1+\frac{n}{n-k}\right).
\]
